/**
 * A durability checkpoint row as returned by `listWorkspaceCheckpoints`.
 */
type Checkpoint = {
    nodeId: string;
    iteration?: number;
    seq: number;
    attempt?: number;
    jjCommitId: string;
    jjCwd: string;
    createdAtMs?: number;
    runId?: string;
    ownerNodeId?: string;
    ownerIteration?: number;
};

export { type Checkpoint, RESTORE_TIMEOUT_MS, defaultCaptureCurrent, defaultRevert, pickTargetCheckpoint, runRestoreOnce };
